style.css:
@-moz-document domain("chatgpt.com") {
/* 1. Reset Main Backgrounds */
    body, .main-viewport, main {
        background-color: #343541 !important;
        color: #ececf1 !important;
    }

    /* 2. Reset Sidebar Background */
    [class*="sidebar"], nav {
        background-color: #202123 !important;
    }

    /* 3. Revert Message Bubbles & Alternate Shading */
    article:nth-child(odd) {
        background-color: #343541 !important;
    }
    article:nth-child(even) {
        background-color: #444654 !important;
        border-top: 1px solid rgba(0,0,0,0.1);
        border-bottom: 1px solid rgba(0,0,0,0.1);
    }

    /* 4. FORCE AGGRESSIVE STRAIGHT-LINED RECTANGLE CHATBAR */
    /* Strips out the oval curvature from the input box, inner wrapper, and parent alignment frames */
    div[class*="composer-parent"],
    div[class*="rt-Box"],
    div[style*="border-radius"],
    form div[class*="overflow-hidden"],
    #prompt-textarea-container,
    .flex.w-full.items-center {
        border-radius: 4px !important; /* Destroys all oval capsules */
    }

    /* Target the exact bottom form wrapper box */
    form, 
    form > div {
        border-radius: 4px !important;
        background-color: #40414f !important;
    }
    
    /* Straighten text block element edge alignment */
    textarea, #prompt-textarea {
        color: #ececf1 !important;
        border-radius: 0px !important;
        padding-left: 10px !important;
    }

    /* 5. RESTORE ORIGINAL OPENAI GREEN AVATAR */
    article:nth-child(even) div[class*="avatar"],
    article:nth-child(even) .agent-avatar,
    div[class*="gizmo-bot-avatar"],
    div[class*="avatar-box"] {
        background-color: #10A37F !important; /* Original 2022 Brand Green */
        border-radius: 4px !important;
    }
    
    article:nth-child(even) div[class*="avatar"] svg,
    div[class*="gizmo-bot-avatar"] svg {
        color: #ffffff !important;
        fill: #ffffff !important;
    }

    /* 6. VINTAGE GREEN BLINKING TYPING CURSOR */
    div[class*="result-streaming"]::after,
    .result-streaming::after {
        content: "▊" !important;
        color: #10A37F !important;
        font-family: monospace !important;
        margin-left: 4px !important;
        animation: blink 0.8s infinite alternate !important;
        display: inline-block !important;
    }

    @keyframes blink {
        0% { opacity: 1; }
        100% { opacity: 0; }
    }

    /* 7. Hide Modern Pill Clutter & Sub-Buttons */
    div[class*="attachments-clutter"],
    button[aria-label*="Search"],
    button[aria-label*="Reason"],
    div[class*="text-token-text-secondary"],
    [class*="rounded-full"] button {
        border-radius: 4px !important; /* Flatten modern circular inner buttons too */
    }
}
